const beautyRituals=[
  {name:'Essentiel Beauté',duration:'60 min',price:450000,copy:'Coiffure soignée, finition et conseil personnalisé.',items:['Diagnostic express','Shampoing & soin','Coiffage ou brushing']},
  {name:'Rituel Éclat',duration:'90 min',price:750000,copy:'Une parenthèse complète pour le visage, les mains et l’allure.',items:['Soin visage éclat','Manucure classique','Mise en beauté']},
  {name:'Signature Jess',duration:'120 min',price:1100000,copy:'Notre expérience la plus généreuse, imaginée autour de vous.',items:['Diagnostic approfondi','Soin visage & massage','Coiffure et finition'],featured:true},
  {name:'Sur mesure',duration:'À définir',price:0,copy:'Composez librement plusieurs prestations selon votre envie.',items:['Durée flexible','Conseil dédié','Estimation immédiate']}
];
function beautyPage(){
  const ritualCards=beautyRituals.map((r,i)=>`<article class="beauty-ritual-card reveal${r.featured?' featured':''}"><div class="beauty-ritual-top"><span>${String(i+1).padStart(2,'0')}</span>${r.featured?'<b>Le plus choisi</b>':''}</div><h3>${r.name}</h3><p>${r.copy}</p><ul>${r.items.map(x=>`<li>${x}</li>`).join('')}</ul><div class="beauty-price">${r.price?`Dès ${r.price.toLocaleString('fr-FR')} GNF`:'Estimation personnalisée'}<small>${r.duration}</small></div><button type="button" class="beauty-book ghost" data-ritual="${r.name}" data-price="${r.price}">Choisir ce rituel</button></article>`).join('');
  const options=[['Coiffure & brushing',150000,'45 min'],['Tresses protectrices',250000,'90 min'],['Manucure',150000,'45 min'],['Pédicure spa',200000,'60 min'],['Soin visage éclat',250000,'60 min'],['Massage bien-être',300000,'60 min'],['Maquillage événementiel',350000,'75 min'],['Soin des ongles',120000,'35 min']];
  return `<div class="beauty-page">
    <section class="beauty-hero"><div class="beauty-hero-media" aria-hidden="true"></div><div class="beauty-hero-shade"></div><div class="beauty-hero-copy reveal"><p class="kicker">Jess Beauty · Nongo, Conakry</p><h1>Votre beauté.<br>Votre rythme.<br><em>Votre moment.</em></h1><p>Salon, onglerie, spa et mise en beauté réunis dans une expérience attentive, élégante et profondément personnelle.</p><div class="actions"><a class="cta" href="#beauty-composer">Composer mon rituel</a><a class="ghost" href="#beauty-booking">Réserver maintenant</a></div><div class="beauty-trust"><span>Diagnostic personnalisé</span><span>Hygiène exigeante</span><span>Confirmation humaine</span></div></div></section>
    <section class="beauty-section beauty-intro reveal"><div><p class="kicker">La maison Jess Beauty</p><h2>Un salon pensé comme une parenthèse.</h2></div><div><p class="beauty-lead">Chaque rendez-vous commence par l’écoute. Votre style, votre temps et vos préférences guident les gestes de notre équipe.</p><p>De la coiffure aux soins, nous construisons un parcours fluide, avec des prestations clairement expliquées et une réservation confirmée directement par l’équipe Jess.</p><a class="text-link" href="#beauty-rituals">Découvrir les rituels →</a></div></section>
    <section class="beauty-values" aria-label="Nos engagements"><article><b>01</b><h3>Diagnostic</h3><p>Comprendre votre besoin avant de commencer.</p></article><article><b>02</b><h3>Hygiène</h3><p>Matériel et espaces préparés avec soin.</p></article><article><b>03</b><h3>Sur mesure</h3><p>Des gestes adaptés à votre style.</p></article><article><b>04</b><h3>Ponctualité</h3><p>Un créneau organisé et confirmé.</p></article></section>
    <section id="beauty-rituals" class="beauty-section"><div class="beauty-heading"><div><p class="kicker">Nos rituels</p><h2>Choisissez votre niveau d’attention.</h2></div><p>Tarifs fictifs de démonstration, à confirmer avec le salon avant le rendez-vous.</p></div><div class="beauty-ritual-grid">${ritualCards}</div></section>
    <section id="beauty-composer" class="beauty-composer"><div class="beauty-composer-media reveal"><div><span>Votre rituel</span><strong>100% personnel</strong></div></div><div class="beauty-config reveal"><p class="kicker">Configurateur</p><h2>Composez votre moment.</h2><p>Sélectionnez une ou plusieurs prestations. L’estimation évolue instantanément, sans paiement en ligne.</p><div class="beauty-option-grid">${options.map((o,i)=>`<button type="button" class="beauty-option" data-beauty-option data-label="${o[0]}" data-price="${o[1]}"><span><i>${String(i+1).padStart(2,'0')}</i>${o[0]}</span><small>+ ${o[1].toLocaleString('fr-FR')} GNF · ${o[2]}</small></button>`).join('')}</div><div class="beauty-estimate"><div><span>Estimation indicative</span><strong id="beautyTotal">0 GNF</strong></div><small>Prix fictifs à confirmer · aucun paiement sur le site</small></div><button type="button" id="beautyToBooking" class="cta">Continuer vers la réservation</button></div></section>
    <section class="beauty-section beauty-process"><div class="beauty-heading"><div><p class="kicker">Votre expérience</p><h2>Quatre étapes, tout simplement.</h2></div></div><div class="beauty-process-grid"><article class="reveal"><b>01</b><h3>Vous choisissez</h3><p>Un rituel ou une combinaison de services.</p></article><article class="reveal"><b>02</b><h3>Vous demandez</h3><p>La date, l’heure et vos préférences.</p></article><article class="reveal"><b>03</b><h3>Nous confirmons</h3><p>L’équipe valide disponibilité, durée et tarif réel.</p></article><article class="reveal"><b>04</b><h3>Vous profitez</h3><p>Votre place est préparée avant votre arrivée.</p></article></div></section>
    <section class="beauty-safety"><div class="beauty-safety-media" role="img" aria-label="Espace spa Jess Beauty"></div><div class="beauty-safety-copy reveal"><p class="kicker">Confort & confiance</p><h2>Vous gardez le contrôle de votre expérience.</h2><p>Préférences, sensibilité, ambiance ou contraintes de temps : vous pouvez les indiquer dès la réservation. L’équipe vous écoute et confirme chaque détail avant le rendez-vous.</p><ul><li>Accueil et diagnostic avant la prestation</li><li>Matériel préparé entre chaque rendez-vous</li><li>Produits et options expliqués sur place</li><li>Aucun paiement demandé dans ce prototype</li></ul><blockquote>« Prendre soin de vous commence par vous écouter. »<cite>— L’esprit Jess Beauty</cite></blockquote></div></section>
    <section id="beauty-booking" class="beauty-section beauty-booking"><div class="beauty-booking-intro"><p class="kicker">Réservation assistée</p><h2>Préparez votre rendez-vous.</h2><p>Votre demande est transmise par WhatsApp. Le salon confirme ensuite le créneau, le prix et les modalités.</p></div><div class="beauty-booking-shell"><ol class="beauty-stepper"><li class="active">Rituel</li><li>Date</li><li>Coordonnées</li><li>Préférences</li><li>Résumé</li></ol><form class="beauty-booking-form">
      <div class="beauty-booking-panel" data-beauty-step="0"><span class="beauty-step-count">Étape 1 sur 5</span><h3>Quel moment souhaitez-vous ?</h3><label>Rituel<select required name="rituel"><option value="">Choisir un rituel</option>${beautyRituals.map(r=>`<option>${r.name}</option>`).join('')}</select></label><label>Prestations sélectionnées<textarea name="prestations" id="beautyServices" rows="3" placeholder="Vous pouvez aussi composer votre rituel ci-dessus"></textarea></label></div>
      <div class="beauty-booking-panel" data-beauty-step="1" hidden><span class="beauty-step-count">Étape 2 sur 5</span><h3>Quand souhaitez-vous venir ?</h3><div class="beauty-form-grid"><label>Date souhaitée<input required type="date" name="date"></label><label>Heure souhaitée<select required name="heure"><option value="">Choisir une heure</option><option>09:00</option><option>10:30</option><option>12:00</option><option>14:00</option><option>15:30</option><option>17:00</option></select></label></div><p class="beauty-help">Le créneau reste soumis à la confirmation du salon.</p></div>
      <div class="beauty-booking-panel" data-beauty-step="2" hidden><span class="beauty-step-count">Étape 3 sur 5</span><h3>Comment vous joindre ?</h3><div class="beauty-form-grid"><label>Nom complet<input required name="nom" autocomplete="name"></label><label>Téléphone WhatsApp<input required name="telephone" autocomplete="tel" placeholder="+224 …"></label><label>Email facultatif<input type="email" name="email" autocomplete="email"></label></div></div>
      <div class="beauty-booking-panel" data-beauty-step="3" hidden><span class="beauty-step-count">Étape 4 sur 5</span><h3>Vos préférences</h3><label>Ce que l’équipe doit savoir<textarea name="preferences" rows="4" placeholder="Style souhaité, sensibilité, événement, contrainte de temps…"></textarea></label><label class="beauty-check"><input required type="checkbox" name="accord" value="Oui"><span>J’accepte que ces informations soient utilisées uniquement pour répondre à ma demande.</span></label></div>
      <div class="beauty-booking-panel" data-beauty-step="4" hidden><span class="beauty-step-count">Étape 5 sur 5</span><h3>Vérifiez votre demande.</h3><div id="beautySummary" class="beauty-summary"></div><p class="beauty-help">Aucun paiement n’est réalisé ici. WhatsApp s’ouvrira pour envoyer la demande à Jess Beauty.</p></div>
      <div class="beauty-booking-actions"><button type="button" class="ghost" data-beauty-back hidden>Retour</button><button type="button" class="cta" data-beauty-next>Continuer</button><button type="submit" class="cta" data-beauty-submit hidden>Envoyer via WhatsApp</button></div>
    </form></div></section>
    <section class="beauty-section beauty-visit"><div><p class="kicker">Votre visite</p><h2>Jess Beauty vous accueille à Nongo.</h2><p>Salon, spa et onglerie sur rendez-vous. Les horaires, la disponibilité et le tarif final sont confirmés directement par l’équipe.</p></div><div class="beauty-visit-cards"><article><span>01</span><h3>Au salon</h3><p>Une expérience complète dans l’espace Jess Beauty.</p></article><article><span>02</span><h3>Événements</h3><p>Mariage, cérémonie et préparation spéciale sur demande.</p></article><article><span>03</span><h3>Conseil privé</h3><p>Un échange avant rendez-vous pour les besoins complexes.</p></article></div></section>
    <section class="beauty-section beauty-faq"><div><p class="kicker">Questions fréquentes</p><h2>Avant votre rendez-vous.</h2></div><div><details><summary>Les prix affichés sont-ils définitifs ?</summary><p>Non. Ils illustrent le parcours de réservation. L’équipe confirme le tarif réel selon la prestation, la durée et les produits nécessaires.</p></details><details><summary>Puis-je combiner plusieurs services ?</summary><p>Oui. Utilisez le configurateur puis transmettez votre sélection dans la demande de rendez-vous.</p></details><details><summary>Ma réservation est-elle confirmée immédiatement ?</summary><p>La demande est d’abord envoyée sur WhatsApp. Le rendez-vous devient confirmé après la réponse de l’équipe Jess Beauty.</p></details><details><summary>Le site encaisse-t-il un paiement ?</summary><p>Non. Aucun paiement ni aucune donnée bancaire ne sont collectés sur ce prototype.</p></details></div></section>
    <section class="beauty-final"><p class="kicker">Votre moment commence ici</p><h2>Prête à vous accorder du temps ?</h2><p>Composez votre rituel et laissez l’équipe Jess Beauty préparer la suite.</p><a class="cta" href="#beauty-booking">Réserver mon moment</a></section>
    <a class="beauty-mobile-cta" href="#beauty-booking">Réserver chez Jess Beauty</a>
  </div>`;
}
