  const ritualCards=beautyRituals.map((r,i)=>`<article class="beauty-v2-ritual reveal${r.featured?' featured':''}"><span>${String(i+1).padStart(2,'0')}</span><small>${r.duration}</small><h3>${r.name}</h3><p>${r.copy}</p><ul>${r.items.map(x=>`<li>${x}</li>`).join('')}</ul><strong>${r.price?`Dès ${r.price.toLocaleString('fr-FR')} GNF`:'Sur devis'}</strong><button type="button" class="beauty-book" data-ritual="${r.name}" data-price="${r.price}">Choisir ce rituel</button></article>`).join('');
