function panelFor(tab){const data=tab==='Voyager'?{title:'Où souhaitez-vous aller ?',kind:'Voyage',fields:travelFields,button:'Transmettre via WhatsApp',image:'destinations.jpg',alt:'Destination de voyage'}:tab==='Colis'?{title:'Préparons votre envoi.',kind:'Colis',fields:parcelFields,button:'Transmettre via WhatsApp',image:'famille-colis.jpg',alt:'Préparation d’un colis'}:tab==='Beauté'?{title:'Réservez votre moment.',kind:'Beauté',fields:beautyFields,button:'Transmettre via WhatsApp',image:'bien-etre.jpg',alt:'Soin beauté et bien-être'}:{title:'Préparez votre séjour.',kind:'Appartement',fields:'<label>Arrivée<input required type="date" name="arrivee"></label><label>Départ<input required type="date" name="depart"></label><label>Voyageurs<input required type="number" min="1" value="1" name="voyageurs"></label><label>Téléphone<input required name="telephone"></label>',button:'Voir les appartements',image:'suite-kipe-v2.jpg',alt:'Appartement Jess Paradise'};return `<div class="service-panel-layout"><div class="service-panel-form"><h2>${data.title}</h2>${form(data.kind,data.fields,data.button)}</div><figure class="service-panel-banner"><img src="assets/generated/${data.image}" alt="${data.alt}"><figcaption>${tab}<span>Une équipe Jess vous accompagne.</span></figcaption></figure></div>`}
function requestMessage(kind,data){const lines=Object.entries(data).map(([k,v])=>`${k.replace(/_/g,' ')} : ${v}`).join('\n');return `Bonjour ${kind==='Donation'?'Jess Children and Women':'Jess Holding'},\nJe souhaite transmettre une demande ${kind.toLowerCase()} :\n${lines}\nMerci de me confirmer les informations, la disponibilité et les conditions.`}
function bindForms(){document.querySelectorAll('form:not(.beauty-booking-form)').forEach(f=>f.onsubmit=e=>{e.preventDefault();const kind=f.dataset.kind,data=Object.fromEntries(new FormData(f));if(kind==='Suivi'){f.nextElementSibling.textContent='Référence non trouvée dans cette démonstration. Contactez le service client pour un suivi réel.';f.nextElementSibling.style.display='block';return}sessionStorage.setItem(`jess-${kind}`,JSON.stringify(data));window.open(wa(requestMessage(kind,data)),'_blank','noopener')})}
function bindBeauty(){
  const page=document.querySelector('.beauty-page');if(!page)return;
  const selected=new Map(),total=$('#beautyTotal'),services=$('#beautyServices'),ritualSelect=document.querySelector('.beauty-booking-form [name="rituel"]');
  const sync=()=>{const items=[...selected.keys()],amount=[...selected.values()].reduce((a,b)=>a+b,0);if(total)total.textContent=`${amount.toLocaleString('fr-FR')} GNF`;if(services)services.value=items.join(', ')};
  document.querySelectorAll('[data-beauty-option]').forEach(b=>b.onclick=()=>{b.classList.toggle('active');b.setAttribute('aria-pressed',String(b.classList.contains('active')));b.classList.contains('active')?selected.set(b.dataset.label,Number(b.dataset.price)):selected.delete(b.dataset.label);sync()});
  document.querySelectorAll('.beauty-book').forEach(b=>b.onclick=()=>{ritualSelect.value=b.dataset.ritual;document.querySelector('#beauty-booking').scrollIntoView({behavior:'smooth',block:'start'})});
  $('#beautyToBooking')?.addEventListener('click',()=>{if(!selected.size){toast('Sélectionnez au moins une prestation.');return}ritualSelect.value='Sur mesure';sync();document.querySelector('#beauty-booking').scrollIntoView({behavior:'smooth',block:'start'})});
  const form=document.querySelector('.beauty-booking-form'),panels=[...document.querySelectorAll('[data-beauty-step]')],steps=[...document.querySelectorAll('.beauty-stepper li')],back=form.querySelector('[data-beauty-back]'),next=form.querySelector('[data-beauty-next]'),submit=form.querySelector('[data-beauty-submit]');let current=0;
  const summary=()=>{const data=Object.fromEntries(new FormData(form));$('#beautySummary').innerHTML=`<dl><div><dt>Rituel</dt><dd>${data.rituel||'—'}</dd></div><div><dt>Prestations</dt><dd>${data.prestations||'—'}</dd></div><div><dt>Date</dt><dd>${data.date||'—'} · ${data.heure||'—'}</dd></div><div><dt>Nom</dt><dd>${data.nom||'—'}</dd></div><div><dt>Téléphone</dt><dd>${data.telephone||'—'}</dd></div><div><dt>Préférences</dt><dd>${data.preferences||'Aucune précision'}</dd></div><div><dt>Estimation</dt><dd>${total?.textContent||'À confirmer'}</dd></div></dl>`};
  const show=()=>{panels.forEach((p,i)=>p.hidden=i!==current);steps.forEach((s,i)=>{s.classList.toggle('active',i===current);s.classList.toggle('done',i<current)});back.hidden=current===0;next.hidden=current===panels.length-1;submit.hidden=current!==panels.length-1;if(current===panels.length-1)summary()};
  const valid=()=>{const controls=[...panels[current].querySelectorAll('input,select,textarea')];for(const c of controls)if(!c.checkValidity()){c.reportValidity();return false}return true};
  next.onclick=()=>{if(valid()){current=Math.min(current+1,panels.length-1);show()}};back.onclick=()=>{current=Math.max(0,current-1);show()};
  form.onsubmit=e=>{e.preventDefault();if(!valid())return;const data=Object.fromEntries(new FormData(form));const message=`Bonjour Jess Beauty,\nJe souhaite demander un rendez-vous.\n\nRituel : ${data.rituel}\nPrestations : ${data.prestations||'À préciser'}\nEstimation indicative : ${total?.textContent||'À confirmer'}\nDate et heure : ${data.date} à ${data.heure}\nNom : ${data.nom}\nTéléphone : ${data.telephone}\nEmail : ${data.email||'Non renseigné'}\nPréférences : ${data.preferences||'Aucune'}\n\nMerci de me confirmer la disponibilité, le tarif réel et les modalités.`;sessionStorage.setItem('jess-beauty-booking',JSON.stringify(data));window.open(wa(message),'_blank','noopener')};show();
}
function bindTravel(){
  const page=document.querySelector('.travel-dream-page');if(!page)return;
  const money=n=>`${Number(n).toLocaleString('fr-FR')} GNF`;
  const openTravel=data=>{const message=`Bonjour Jess Voyages,\nJe souhaite recevoir une proposition de voyage.\n\n${Object.entries(data).map(([k,v])=>`${k.replace(/_/g,' ')} : ${v}`).join('\n')}\n\nMerci de me confirmer le tarif, les disponibilités et les formalités.`;window.open(wa(message),'_blank','noopener')};
  const heroForm=document.querySelector('.travel-hero-search');heroForm.onsubmit=e=>{e.preventDefault();openTravel(Object.fromEntries(new FormData(heroForm)))};const heroBudget=heroForm.querySelector('[name="budget"]'),heroSmall=heroBudget.parentElement.querySelector('small');heroBudget.oninput=()=>heroSmall.textContent=money(String(heroBudget.value).replace(/\D/g,'')||0);
  document.querySelectorAll('[data-travel-destination]').forEach(b=>b.onclick=()=>openTravel({destination:b.dataset.travelDestination,forfait_indicatif:money(b.dataset.travelPrice),depart:'Conakry'}));
  const range=$('#travelBudget'),label=$('#travelBudgetLabel'),total=$('#travelBudgetTotal'),suggestion=$('#travelSuggestion'),meta=$('#travelSuggestionMeta'),score=$('#travelScore');
  const updateBudget=()=>{const value=Number(range.value);label.textContent=total.textContent=money(value);const pick=value<9000000?travelFeatured[0]:value<12500000?travelFeatured[4]:value<16000000?travelFeatured[1]:value<19000000?travelFeatured[3]:travelFeatured[2];suggestion.textContent=pick.city;meta.textContent=`${pick.tag} · ${pick.days} jours · Sur mesure`;score.textContent=`${Math.min(97,82+Math.round(value/5000000))}%`};range.oninput=updateBudget;updateBudget();
  $('#travelPlannerCta').onclick=()=>openTravel({budget:money(range.value),suggestion:suggestion.textContent,depart:'Conakry'});
  const quote=document.querySelector('.travel-quote-form');quote.onsubmit=e=>{e.preventDefault();if(!quote.reportValidity())return;openTravel(Object.fromEntries(new FormData(quote)))};
}
let carouselTimer;
function bindCarousel(){
  clearInterval(carouselTimer);const slides=[...document.querySelectorAll('.carousel-slide')];if(!slides.length)return;let current=0;
  const show=index=>{current=(index+slides.length)%slides.length;slides.forEach((s,i)=>s.classList.toggle('active',i===current));document.querySelectorAll('[data-carousel-dot]').forEach((d,i)=>d.classList.toggle('active',i===current))};
  $('[data-carousel-prev]').onclick=()=>show(current-1);$('[data-carousel-next]').onclick=()=>show(current+1);document.querySelectorAll('[data-carousel-dot]').forEach(d=>d.onclick=()=>show(Number(d.dataset.carouselDot)));
  if(!document.body.classList.contains('motion-off'))carouselTimer=setInterval(()=>show(current+1),4800);
}
function bindImmersive(){
  window.removeEventListener('scroll',window.__jessJourney);const journeys=[...document.querySelectorAll('.immersive-journey')];if(!journeys.length)return;
  const update=()=>journeys.forEach(j=>{const range=Math.max(1,j.offsetHeight-innerHeight),top=j.getBoundingClientRect().top+scrollY,p=Math.max(0,Math.min(1,(scrollY-top)/range));const object=j.querySelector('.motion-object'),meter=j.querySelector('.journey-meter i'),copy=j.querySelector('.scene-copy')||j.querySelector('.travel-hero-content');if(j.dataset.journey==='plane')object.style.transform=`translate3d(${p*82-28}vw,${48-p*67}vh,0) rotate(${-4-p*12}deg) scale(${.68+p*.38})`;else object.style.transform=`translate3d(${p*65-8}vw,${8+p*47+Math.sin(p*22)*5}vh,0) rotate(${p*430-22}deg) scale(${.7+p*.24})`;if(meter)meter.style.width=`${p*100}%`;if(copy)copy.style.opacity=String(Math.max(.12,1-p*1.25));j.style.setProperty('--journey-progress',p)});
  window.__jessJourney=()=>requestAnimationFrame(update);window.addEventListener('scroll',window.__jessJourney,{passive:true});update();
}
let countdownTimer;
function bindCountdown(){
  clearInterval(countdownTimer);const box=document.querySelector('[data-countdown]');if(!box)return;
  const update=()=>{const distance=Math.max(0,new Date(box.dataset.countdown)-new Date()),day=Math.floor(distance/86400000),hour=Math.floor(distance%86400000/3600000),minute=Math.floor(distance%3600000/60000),second=Math.floor(distance%60000/1000);box.querySelector('[data-days]').textContent=String(day).padStart(2,'0');box.querySelector('[data-hours]').textContent=String(hour).padStart(2,'0');box.querySelector('[data-minutes]').textContent=String(minute).padStart(2,'0');box.querySelector('[data-seconds]').textContent=String(second).padStart(2,'0')};
  update();countdownTimer=setInterval(update,1000);
}
function bind(){
  document.querySelectorAll('.tabs button').forEach(b=>b.onclick=()=>{document.querySelectorAll('.tabs button').forEach(x=>x.classList.remove('active'));b.classList.add('active');$('#tabPanel').innerHTML=panelFor(b.dataset.tab);bindForms()});if($('#tabPanel'))document.querySelector('.tabs button.active').click();
  document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-filter]').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.querySelectorAll('.product-card').forEach(c=>c.hidden=b.dataset.filter!=='all'&&c.dataset.category!==b.dataset.filter)});
  const cart=JSON.parse(localStorage.getItem('jess-cart')||'[]');if($('#cartCount'))$('#cartCount').textContent=cart.length;document.querySelectorAll('.add-cart').forEach(b=>b.onclick=()=>{const c=JSON.parse(localStorage.getItem('jess-cart')||'[]');c.push(b.dataset.name);localStorage.setItem('jess-cart',JSON.stringify(c));if($('#cartCount'))$('#cartCount').textContent=c.length;toast(`${b.dataset.name} ajouté à votre sélection fictive.`)});
  document.querySelectorAll('.destination-card').forEach(c=>{c.onclick=()=>openDialog('Voyage',c.dataset.destination,c.dataset.price);c.onkeydown=e=>{if(e.key==='Enter')c.click()}});document.querySelectorAll('.property-book').forEach(b=>b.onclick=()=>openDialog('Appartement',b.dataset.property,''));document.querySelectorAll('.donate').forEach(b=>b.onclick=()=>{document.querySelector('[name="campagne"]').value=b.dataset.campaign;document.querySelector('.donation-panel').scrollIntoView({behavior:'smooth'})});
  document.querySelectorAll('#main img').forEach(img=>{img.decoding='async';if(!img.closest('.motion-object')&&!img.closest('.hero'))img.loading='lazy'});
  bindCarousel();bindImmersive();bindCountdown();bindForms();bindBeauty();bindTravel();const io=new IntersectionObserver(es=>es.forEach(e=>e.isIntersecting&&e.target.classList.add('in-view')),{threshold:.12});document.querySelectorAll('.reveal').forEach(x=>io.observe(x));window.JessI18n?.apply(main);
}
function openDialog(kind,item,price){let d=$('#requestDialog');if(!d){d=document.createElement('dialog');d.id='requestDialog';document.body.appendChild(d)}const fields=kind==='Voyage'?`<label>Destination<input name="destination" value="${item}" readonly></label><label>Forfait démo<input name="forfait" value="${price} GNF" readonly></label><label>Date aller<input required type="date" name="aller"></label><label>Date retour<input required type="date" name="retour"></label><label>Nom<input required name="nom"></label><label>Téléphone<input required name="telephone"></label>`:`<label>Logement<input name="logement" value="${item}" readonly></label><label>Arrivée<input required type="date" name="arrivee"></label><label>Départ<input required type="date" name="depart"></label><label>Nom<input required name="nom"></label><label>Téléphone<input required name="telephone"></label>`;d.innerHTML=`<button class="dialog-close" aria-label="Fermer">×</button><p class="kicker">Demande rapide</p><h2>${item}</h2>${form(kind,fields,'Transmettre via WhatsApp')}`;d.querySelector('.dialog-close').onclick=()=>d.close();bindForms();d.showModal()}
function toast(m){document.querySelector('.toast')?.remove();const t=document.createElement('div');t.className='toast';t.textContent=m;document.body.appendChild(t);setTimeout(()=>t.remove(),2800)}
function render(){const raw=location.pathname.replace(/\/$/,'')||'/';const path=BASE&&raw.startsWith(BASE)?(raw.slice(BASE.length)||'/'):raw;if(path==='/groupe'){history.replaceState({},'',`${BASE}/#groupe`);main.innerHTML=home()}else main.innerHTML=path==='/'?home():(hubs[path]?hubs[path]():page('Page introuvable.','Erreur 404','Cette trajectoire ne mène à aucune page.','<a class="cta" href="/">Retour à l’accueil</a>'));const english=window.JessI18n?.lang==='en';window.scrollTo(0,0);bind();document.title=path==='/'?(english?'Jess Holding — Your projects, made simpler':'Jess Holding — Vos projets, simplement'):`${main.querySelector('h1')?.textContent||'Jess Holding'} — Jess Holding`;if(location.hash)setTimeout(()=>document.querySelector(location.hash)?.scrollIntoView(),50)}
function navigate(path){const u=new URL(path,location.origin);history.pushState({},'',`${BASE}${u.pathname}${u.hash}`);render()}
document.addEventListener('click',e=>{const a=e.target.closest('a[href^="/"]');if(a&&!a.target){e.preventDefault();const u=new URL(a.href);navigate(u.pathname+u.hash)}if(e.target.closest('#nav a')){$('#nav').classList.remove('open');$('.menu').setAttribute('aria-expanded','false')}});
window.onpopstate=render;$('.menu').onclick=()=>{$('#nav').classList.toggle('open');$('.menu').setAttribute('aria-expanded',$('#nav').classList.contains('open'))};
window.JessI18n?.install();
const langButton=$('.lang-toggle');langButton.onclick=()=>window.JessI18n.set(window.JessI18n.lang==='en'?'fr':'en');
const themeButton=$('.theme-toggle');
const setTheme=theme=>{document.documentElement.dataset.theme=theme;localStorage.setItem('jess-theme',theme);const english=window.JessI18n?.lang==='en';themeButton.textContent=theme==='dark'?(english?'Light':'Clair'):(english?'Dark':'Sombre');themeButton.setAttribute('aria-label',theme==='dark'?(english?'Enable light mode':'Activer le mode clair'):(english?'Enable dark mode':'Activer le mode sombre'))};
themeButton.onclick=()=>setTheme(document.documentElement.dataset.theme==='dark'?'light':'dark');setTheme(localStorage.getItem('jess-theme')||'light');
const universMenu=document.querySelector('#nav details');if(matchMedia('(hover:hover) and (pointer:fine)').matches){let menuCloseTimer;universMenu.addEventListener('mouseenter',()=>{clearTimeout(menuCloseTimer);universMenu.open=true});universMenu.addEventListener('mouseleave',()=>{menuCloseTimer=setTimeout(()=>universMenu.open=false,650)});universMenu.querySelector('.mega').addEventListener('mouseenter',()=>clearTimeout(menuCloseTimer))}universMenu.querySelector('summary').addEventListener('click',e=>{e.preventDefault();universMenu.open=!universMenu.open});document.addEventListener('click',e=>{if(!universMenu.contains(e.target))universMenu.open=false});
const motion=$('.motion-toggle');const setMotion=off=>{document.body.classList.toggle('motion-off',off);motion.setAttribute('aria-pressed',String(off));motion.textContent=off?'Activer animations':'Réduire animations';bindCarousel();window.JessI18n?.apply(motion.parentElement)};motion.onclick=()=>setMotion(!document.body.classList.contains('motion-off'));setMotion(false);render();
